<?php
session_start();
require __DIR__ . '/database.php';

if (empty($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}
$csrf = $_SESSION['csrf_token'];

$today = date('Y-m-d');
$stmt = $db->prepare('SELECT * FROM lunches WHERE lunch_date=? ORDER BY meal_time ASC,id DESC');
$stmt->execute([$today]);
$lunches = $stmt->fetchAll();
$totalToday = count($lunches);
$totalAll = (int)$db->query('SELECT COUNT(*) FROM lunches')->fetchColumn();
$daysLogged = (int)$db->query('SELECT COUNT(DISTINCT lunch_date) FROM lunches')->fetchColumn();

$schedule = [
 ['08:00','09:00','Breakfast','Idli / dosa / chapati + egg','🍳'],
 ['10:30','11:00','Morning Snack','Banana or another fruit','🍌'],
 ['12:00','13:00','Lunch','Rice + vegetables + fish/chicken/egg/dal','🍚'],
 ['16:30','17:00','Evening Snack','Milk + guava + peanuts/almonds','🥛'],
 ['20:00','21:00','During Duty','2 boiled eggs + banana','🥚'],
 ['22:15','22:45','Dinner','Rice + fish/egg/chicken + vegetables','🍛']
];
function displayDate(string $iso): string { $t=strtotime($iso); return $t?date('d-m-Y',$t):$iso; }
function displayTime(string $iso): string { $t=strtotime($iso); return $t?date('h:i A',$t):$iso; }
?>
