ation:none;font-weight:800}.empty{text-align:center;color:var(--muted);padding:25px 8px}.flash{padding:11px 14px;border-radius:12px;margin:12px 0;background:#ecfdf5;color:#166534;border:1px solid #bbf7d0;font-size:13px;font-weight:700}.alert-banner{position:fixed;left:14px;right:14px;bottom:16px;max-width:600px;margin:auto;background:#111827;color:#fff;padding:15px 17px;border-radius:15px;box-shadow:0 14px 35px rgba(0,0,0,.25);transform:translateY(150%);transition:.3s;z-index:50}.alert-banner.show{transform:translateY(0)}.footer{text-align:center;color:var(--muted);font-size:11px;margin-top:20px}@media(max-width:680px){.container{width:min(100% - 18px,1050px);padding-top:10px}.hero{padding:21px;border-radius:21px}.hero h1{font-size:26px}.date-box{display:none}.stats{gap:8px}.stat{padding:13px}.stat strong{font-size:21px}.schedule,.actions,.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.card{padding:16px}}
