<section class="card"><div class="section-head"><h2>Today's Entries</h2><small><?=htmlspecialchars(displayDate($today))?></small></div><?php if(!$lunches):?><div class="empty">No food entries recorded today.<br>Add your first meal above.</div><?php else:?><div class="entries"><?php foreach($lunches as $item):?><article class="entry"><div class="entry-top"><div class="food"><?=htmlspecialchars($item['food_item'])?></div><div class="badge"><?=htmlspecialchars($item['meal_type']??'Lunch')?></div></div><div class="meta">📅 <?=htmlspecialchars(displayDate($item['lunch_date']))?> · ⏰ <?=htmlspecialchars($item['meal_time']??'')?> · <?=htmlspecialchars(displayTime($item['recorded_time']??''))?></div><?php if(!empty($item['quantity'])):?><div class="quantity"><strong>Quantity:</strong> <?=htmlspecialchars($item['quantity'])?></div><?php endif;?><?php if(!empty($item['notes'])):?><div class="notes">📝 <?=htmlspecialchars($item['notes'])?></div><?php endif;?><div class="entry-actions"><a class="edit" href="edit.php?id=<?=urlencode($item['id'])?>">Edit</a><a class="delete" href="delete.php?id=<?=urlencode($item['id'])?>&csrf_token=<?=urlencode($csrf)?>" onclick="return confirm('Delete this food entry?');">Delete</a></div></article><?php endforeach;?></div><?php endif;?></section>
