<div class="footer">Lunch Food Log · Secure SQLite storage · Dates displayed as DD-MM-YYYY</div></main><div id="mealAlertBanner" class="alert-banner"></div><script src="assets/meal-alert.js"></script><script>
function isoFromDisplay(v){const m=v.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m)return null;const d=+m[1],mo=+m[2],y=+m[3],x=new Date(Date.UTC(y,mo-1,d));if(x.getUTCFullYear()!=y||x.getUTCMonth()!=mo-1||x.getUTCDate()!=d)return null;return `${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;}
document.getElementById('foodForm').addEventListener('submit',function(e){const iso=isoFromDisplay(document.getElementById('date_display').value);if(!iso){e.preventDefault();alert('Please enter a valid date in DD-MM-YYYY format.');return;}document.getElementById('lunch_date').value=iso;});
</script></body></html>
